// Image adapter (CHG-0098). A provider-neutral interface for studio test frames, keyframes and (piece C) Scene Pack stills. The first
// implementation is the OpenAI Images API. Every call is metered through the ledger (reserveApiCall / finishApiCall); an unknown price
// is recorded as unknown, never zero. Generated bytes go to the private studio file store and are tagged AI generated.
import { randomUUID } from "node:crypto";
import { finishApiCall, normalizeApiUsage, reserveApiCall } from "./costs";
import { providerErrorDetail, redactProviderText } from "./providers";
import type { Principal, Project, StudioAssetRef } from "./model";
import type { Repository } from "./repository";
import { sniffMime } from "./studio";
import { putStudioFile, studioKey } from "./studio-store";
import { mediaInfo } from "./studio-media";

/** Sizes every supported model accepts. 1:1 for Scene Pack test frames; 2:3 portrait is the nearest to 4:5 and 9:16. */
export type ImageSize = "1024x1024" | "1024x1536" | "1536x1024";
export const IMAGE_SIZES: readonly ImageSize[] = ["1024x1024", "1024x1536", "1536x1024"];
export type ImageReference = { bytes: Buffer; mime: string; name?: string };
export type ImageRequest = { prompt: string; size: ImageSize; references?: ImageReference[] };
export type ImageResult = { bytes: Buffer; mime: string; usage: Record<string, number>; rawUsage?: Record<string, unknown>; providerRequestId?: string };
/** Provider-neutral image generation. Implementations throw ImageProviderError with the provider's own (redacted) message. */
export type ImageProvider = { provider: string; model: string; generateImage(request: ImageRequest): Promise<ImageResult> };
/** `outcome` tells the ledger whether the call surely produced nothing ("failed") or may have been billed ("unknown"). */
export class ImageProviderError extends Error {
  constructor(message: string, readonly outcome: "failed" | "unknown", readonly usage: Record<string, number> = {}, readonly providerRequestId?: string) {
    super(message);
  }
}
export const MAX_IMAGE_PROMPT = 4000;
const TRANSIENT = new Set([429, 500, 502, 503, 504]);
const retryWaits = () => (process.env.PORT67_PROVIDER_RETRY === "off" ? [] : (process.env.PORT67_PROVIDER_RETRY_MS || "3000,8000").split(",").map(Number).filter((n) => Number.isFinite(n) && n >= 0).slice(0, 3));
const usageOf = (u: unknown): Record<string, number> => {
  const out: Record<string, number> = {};
  if (!u || typeof u !== "object") return out;
  const o = u as Record<string, unknown>;
  for (const k of ["input_tokens", "output_tokens", "total_tokens"]) if (typeof o[k] === "number" && Number.isFinite(o[k]) && (o[k] as number) >= 0) out[k] = o[k] as number;
  return out;
};

/** OpenAI Images: POST /v1/images/generations, or /v1/images/edits when reference images are supplied. Reads the base64 image. */
export function openAiImageProvider(selection: { model: string; key: string }, fetcher: typeof fetch = fetch): ImageProvider {
  const { model, key } = selection;
  const once = async (request: ImageRequest): Promise<{ status: number; data: Record<string, unknown>; requestId?: string }> => {
    const prompt = request.prompt.slice(0, MAX_IMAGE_PROMPT);
    const legacy = /^dall-e/.test(model);
    let init: RequestInit;
    let url = "https://api.openai.com/v1/images/generations";
    if (request.references?.length) {
      url = "https://api.openai.com/v1/images/edits";
      const form = new FormData();
      form.append("model", model);
      form.append("prompt", prompt);
      form.append("size", request.size);
      request.references.slice(0, 8).forEach((r, i) => form.append("image[]", new Blob([new Uint8Array(r.bytes)], { type: r.mime }), r.name || `reference-${i + 1}`));
      init = { method: "POST", headers: { authorization: `Bearer ${key}` }, body: form };
    } else {
      init = { method: "POST", headers: { authorization: `Bearer ${key}`, "content-type": "application/json" }, body: JSON.stringify({ model, prompt, size: request.size, n: 1, ...(legacy ? { response_format: "b64_json" } : {}) }) };
    }
    const response = await fetcher(url, { ...init, signal: AbortSignal.timeout(180000) });
    let data: Record<string, unknown> = {};
    try { data = (await response.json()) as Record<string, unknown>; } catch { if (response.ok) throw new ImageProviderError("Image provider response was not JSON; no image accepted", "unknown"); }
    return { status: response.status, data, requestId: response.headers.get("x-request-id") || undefined };
  };
  return {
    provider: "openai",
    model,
    async generateImage(request) {
      if (!IMAGE_SIZES.includes(request.size)) throw new ImageProviderError("Unsupported image size", "failed");
      if (!request.prompt.trim()) throw new ImageProviderError("An image prompt is required", "failed");
      let result: Awaited<ReturnType<typeof once>>;
      try {
        result = await once(request);
        for (const wait of retryWaits()) {
          if (!TRANSIENT.has(result.status)) break;
          await new Promise((r) => setTimeout(r, wait));
          result = await once(request);
        }
      } catch (e) {
        if (e instanceof ImageProviderError) throw e;
        const timedOut = e instanceof Error && (e.name === "TimeoutError" || e.name === "AbortError");
        throw new ImageProviderError(timedOut ? "Image provider timed out after 180 seconds; usage unknown" : "Image provider request failed; usage unknown", "unknown");
      }
      const usage = usageOf(result.data.usage);
      if (result.status < 200 || result.status >= 300) {
        const why = providerErrorDetail(result.data as Parameters<typeof providerErrorDetail>[0]);
        throw new ImageProviderError(`Image provider returned ${result.status}${why ? ": " + why : ""}; no image accepted`, "failed", usage, result.requestId);
      }
      const first = Array.isArray(result.data.data) ? (result.data.data[0] as Record<string, unknown> | undefined) : undefined;
      const b64 = typeof first?.b64_json === "string" ? first.b64_json : "";
      if (!b64) throw new ImageProviderError("Image provider returned no image data; no image accepted", "unknown", usage, result.requestId);
      const bytes = Buffer.from(b64, "base64");
      const mime = sniffMime(bytes.subarray(0, 16));
      if (!mime || !mime.startsWith("image/")) throw new ImageProviderError("Image provider returned a file that is not a PNG, JPEG or WebP image", "unknown", usage, result.requestId);
      return { bytes, mime, usage, rawUsage: usage, providerRequestId: result.requestId };
    },
  };
}

/** Provider factory for a resolved selection. Only OpenAI is implemented; another provider fails with a clear message. */
export function imageProviderFor(selection: { provider: string; model: string; key: string }, fetcher?: typeof fetch): ImageProvider {
  if (selection.provider !== "openai") throw new Error("Image generation is only built for OpenAI so far");
  return openAiImageProvider(selection, fetcher);
}

/**
 * One metered image call: reserve a ledger row (agent studio:image), generate, then finish the row with the usage reported.
 * A provider error closes the row as failed (nothing produced) or unknown (may have been billed) and is re-thrown with its message.
 */
export async function meteredImage(repo: Repository, a: Principal, p: Pick<Project,"accountId"|"workspaceId"|"id">, runId: string, provider: ImageProvider, request: ImageRequest, agent = "studio:image"): Promise<ImageResult> {
  if (a.demo) throw new Error("Paid image generation is disabled in the synthetic demo");
  const callId = await reserveApiCall(repo, { accountId: p.accountId || p.workspaceId, workspaceId: p.workspaceId, projectId: p.id, runId, stage: "studio", agent, provider: provider.provider, model: provider.model, actor: a.subject });
  try {
    const result = await provider.generateImage(request);
    await finishApiCall(repo, callId, { status: "completed", usage: normalizeApiUsage(result.usage), rawUsage: result.rawUsage, providerRequestId: result.providerRequestId });
    return result;
  } catch (e) {
    const err = e instanceof ImageProviderError ? e : new ImageProviderError(redactProviderText(e instanceof Error ? e.message : "Image generation failed"), "unknown");
    await finishApiCall(repo, callId, { status: err.outcome, usage: normalizeApiUsage(err.usage), rawUsage: Object.keys(err.usage).length ? err.usage : undefined, providerRequestId: err.providerRequestId }).catch(() => undefined);
    throw err;
  }
}

/** Store generated bytes in the private studio file store and return the reference a piece version keeps (tagged AI generated). */
export async function storeGeneratedImage(p: Project, image: Pick<ImageResult, "bytes" | "mime">, by: string, name: string, model: string): Promise<StudioAssetRef> {
  const id = randomUUID();
  const ref: StudioAssetRef = {
    id,
    name: name.replace(/[^\w .()-]/g, "_").slice(0, 120) || "generated",
    mime: image.mime,
    bytes: image.bytes.length,
    storageKey: studioKey(p.accountId || p.workspaceId, p.id, id, image.mime),
    uploadedAt: new Date().toISOString(),
    uploadedBy: by,
    rights: { source: `AI generated with OpenAI ${model} for this project`, licence: "Generated for this project; the provider's output terms apply" },
    aiDisclosure: "ai_generated",
    // Piece C: the real pixel size, read from the image header, for the channel spec checks.
    ...(mediaInfo(image.bytes, image.mime) || {}),
  };
  await putStudioFile(ref.storageKey, image.bytes, image.mime);
  return ref;
}
